  <div class="container">
    <!-- 로그인/회원가입 -->
    <div class="auth-container" id="authContainer">
      <h1>💰 가계부</h1>

      <div class="error" id="authError"></div>

      <div class="form-group">
        <label for="email">이메일</label>
        <input type="email" id="email" placeholder="<EMAIL>">
      </div>

      <div class="form-group">
        <label for="password">비밀번호</label>
        <input type="password" id="password" placeholder="비밀번호">
      </div>

      <div class="button-group">
        <button class="btn-primary" onclick="login()">로그인</button>
        <button class="btn-secondary" onclick="register()">회원가입</button>
      </div>
    </div>

    <!-- 앱 메인 화면 -->
    <div class="app-container" id="appContainer">
      <div class="app-header">
        <h1>💰 가계부</h1>
        <div>
          <div class="user-email" id="userEmail"></div>
          <button class="btn-secondary" onclick="logout()" style="margin-top: 10px; width: auto;">로그아웃</button>
        </div>
      </div>

      <div class="summary" id="summary">
        <div class="summary-item">
          <div class="summary-label">이번 달 지출</div>
          <div class="summary-value" id="totalExpense">0 원</div>
        </div>
      </div>

      <div class="main-content">
        <div class="add-expense-card">
          <h2>지출 추가</h2>

          <div class="error" id="expenseError"></div>
          <div class="success" id="expenseSuccess"></div>

          <div class="form-group">
            <label for="amount">금액</label>
            <input type="number" id="amount" placeholder="금액 입력" min="0">
          </div>

          <div class="form-group">
            <label for="category">카테고리</label>
            <select id="category" style="width: 100%; padding: 12px; border: 2px solid #e0e0e0; border-radius: 6px;">
              <option value="식비">🍽️ 식비</option>
              <option value="교통">🚗 교통</option>
              <option value="쇼핑">🛍️ 쇼핑</option>
              <option value="기타">📌 기타</option>
            </select>
          </div>

          <div class="form-group">
            <label for="description">설명</label>
            <input type="text" id="description" placeholder="선택사항">
          </div>

          <div class="form-group">
            <label for="date">날짜</label>
            <input type="date" id="date">
          </div>

          <button class="btn-primary" onclick="addExpense()" style="width: 100%;">추가</button>
        </div>

        <div class="expenses-list">
          <h2>지출 목록</h2>
          <div id="expensesList">
            <div class="empty-state">지출 기록이 없습니다</div>
          </div>
        </div>
      </div>
    </div>
  </div>

  <script>
    const API_URL = 'http://localhost:3000/api';

    // 초기화
    function init() {
      const token = localStorage.getItem('token');
      const email = localStorage.getItem('email');

      if (token) {
        showApp(email);
        loadExpenses();
        setTodayDate();
      } else {
        showAuth();
      }
    }

    function setTodayDate() {
      const today = new Date().toISOString().split('T')[0];
      document.getElementById('date').value = today;
    }

    function showAuth() {
      document.getElementById('authContainer').style.display = 'block';
      document.getElementById('appContainer').style.display = 'none';
    }

    function showApp(email) {
      document.getElementById('authContainer').style.display = 'none';
      document.getElementById('appContainer').style.display = 'block';
      document.getElementById('userEmail').textContent = email;
    }

    async function register() {
      const email = document.getElementById('email').value;
      const password = document.getElementById('password').value;
