        '기타': '📌'
      };
      return emojis[category] || '📌';
    }

    function updateSummary(expenses) {
      const currentMonth = new Date().getMonth();
      const currentYear = new Date().getFullYear();

      const thisMonthExpenses = expenses.filter(expense => {
        const expenseDate = new Date(expense.date);
        return expenseDate.getMonth() === currentMonth && expenseDate.getFullYear() === currentYear;
      });

      const total = thisMonthExpenses.reduce((sum, exp) => sum + exp.amount, 0);
      document.getElementById('totalExpense').textContent = total.toLocaleString() + ' 원';
    }

    async function deleteExpense(id) {
      if (!confirm('정말 삭제하시겠습니까?')) return;

      try {
        const response = await fetch(`${API_URL}/expenses/${id}`, {
          method: 'DELETE',
          headers: {
            'Authorization': `Bearer ${localStorage.getItem('token')}`
          }
        });

        if (!response.ok) {
          throw new Error('삭제 실패');
        }

        loadExpenses();
      } catch (error) {
        alert('삭제 실패: ' + error.message);
      }
    }

    function editExpense(id, amount, category, description, date) {
      document.getElementById('amount').value = amount;
      document.getElementById('category').value = category;
      document.getElementById('description').value = description;
      document.getElementById('date').value = date;

      const originalButton = event.target;
      originalButton.textContent = '수정 중...';

      document.getElementById('amount').focus();
    }

    function logout() {
      if (!confirm('로그아웃 하시겠습니까?')) return;
      localStorage.removeItem('token');
      localStorage.removeItem('email');
      showAuth();
      document.getElementById('email').value = '';
      document.getElementById('password').value = '';
    }

