  db.all('SELECT * FROM expenses WHERE user_id = ? ORDER BY date DESC', [req.user.id], (err, rows) => {
    if (err) {
      return res.status(500).json({ error: '지출 조회 실패' });
    }
    res.json(rows || []);
  });
});

