            <input type="text" id="description" placeholder="선택사항">
          </div>

          <div class="form-group">
            <label for="date">날짜</label>
            <input type="date" id="date">
          </div>

          <button class="btn-primary" onclick="app.addExpense()" style="width: 100%;">추가</button>
        </div>

        <div class="expenses-list">
          <h2>지출 목록</h2>
          <div id="expensesList">
            <div class="empty-state">지출 기록이 없습니다</div>
          </div>
        </div>
      </div>
    </div>
  </div>

  <script>
    class ExpenseApp {
      constructor() {
        this.dbName = 'ExpenseDB';
        this.userStore = 'users';
        this.expenseStore = 'expenses';
        this.db = null;
        this.currentUser = null;
        this.init();
      }

      init() {
        const request = indexedDB.open(this.dbName, 1);

        request.onerror = () => {
          console.error('데이터베이스 초기화 실패');
        };

        request.onupgradeneeded = (e) => {
          const db = e.target.result;
          if (!db.objectStoreNames.contains(this.userStore)) {
            db.createObjectStore(this.userStore, { keyPath: 'email' });
          }
          if (!db.objectStoreNames.contains(this.expenseStore)) {
            const store = db.createObjectStore(this.expenseStore, { keyPath: 'id', autoIncrement: true });
            store.createIndex('userEmail', 'userEmail', { unique: false });
            store.createIndex('date', 'date', { unique: false });
          }
        };

        request.onsuccess = (e) => {
          this.db = e.target.result;
          this.checkLogin();
        };
      }

      checkLogin() {
        const currentUser = localStorage.getItem('currentUser');
        if (currentUser) {
          this.currentUser = JSON.parse(currentUser);
          this.showApp();
          this.loadExpenses();
          this.setTodayDate();
        } else {
          this.showAuth();
        }
      }

      showAuth() {
        document.getElementById('authContainer').style.display = 'block';
        document.getElementById('appContainer').style.display = 'none';
      }

      showApp() {
        document.getElementById('authContainer').style.display = 'none';
        document.getElementById('appContainer').style.display = 'block';
        document.getElementById('userEmail').textContent = this.currentUser.email;
      }

      setTodayDate() {
        const today = new Date().toISOString().split('T')[0];
        document.getElementById('date').value = today;
      }

      register() {
        const email = document.getElementById('email').value;
        const password = document.getElementById('password').value;
        const errorEl = document.getElementById('authError');

        errorEl.style.display = 'none';

        if (!email || !password) {
          errorEl.textContent = '이메일과 비밀번호를 입력해주세요';
          errorEl.style.display = 'block';
          return;
        }

        const transaction = this.db.transaction([this.userStore], 'readwrite');
        const store = transaction.objectStore(this.userStore);
        const request = store.get(email);

        request.onsuccess = () => {
          if (request.result) {
            errorEl.textContent = '이미 존재하는 이메일입니다';
            errorEl.style.display = 'block';
            return;
          }

          const user = { email, password: this.hashPassword(password) };
          const addRequest = store.add(user);

          addRequest.onsuccess = () => {
            localStorage.setItem('currentUser', JSON.stringify({ email }));
            this.currentUser = { email };
            this.showApp();
            this.loadExpenses();
            this.setTodayDate();
            document.getElementById('email').value = '';
            document.getElementById('password').value = '';
          };
        };
      }

      login() {
        const email = document.getElementById('email').value;
        const password = document.getElementById('password').value;
        const errorEl = document.getElementById('authError');

        errorEl.style.display = 'none';

        if (!email || !password) {
          errorEl.textContent = '이메일과 비밀번호를 입력해주세요';
          errorEl.style.display = 'block';
          return;
        }

        const transaction = this.db.transaction([this.userStore], 'readonly');
        const store = transaction.objectStore(this.userStore);
        const request = store.get(email);

        request.onsuccess = () => {
          const user = request.result;
          if (!user || !this.verifyPassword(password, user.password)) {
            errorEl.textContent = '이메일 또는 비밀번호가 잘못되었습니다';
            errorEl.style.display = 'block';
            return;
          }

          localStorage.setItem('currentUser', JSON.stringify({ email }));
          this.currentUser = { email };
          this.showApp();
          this.loadExpenses();
          this.setTodayDate();
          document.getElementById('email').value = '';
          document.getElementById('password').value = '';
        };
      }

      logout() {
        if (!confirm('로그아웃 하시겠습니까?')) return;
        localStorage.removeItem('currentUser');
        this.currentUser = null;
        document.getElementById('email').value = '';
        document.getElementById('password').value = '';
        this.showAuth();
      }

      addExpense() {
        const amount = parseFloat(document.getElementById('amount').value);
        const category = document.getElementById('category').value;
        const description = document.getElementById('description').value;
        const date = document.getElementById('date').value;
        const errorEl = document.getElementById('expenseError');
        const successEl = document.getElementById('expenseSuccess');

        errorEl.style.display = 'none';
        successEl.style.display = 'none';

        if (!amount || !date) {
          errorEl.textContent = '금액과 날짜를 입력해주세요';
          errorEl.style.display = 'block';
          return;
        }

        const transaction = this.db.transaction([this.expenseStore], 'readwrite');
        const store = transaction.objectStore(this.expenseStore);
        const expense = {
          userEmail: this.currentUser.email,
          amount,
          category,
          description,
          date,
          createdAt: new Date().toISOString()
        };

        const request = store.add(expense);

        request.onsuccess = () => {
          successEl.textContent = '지출이 추가되었습니다';
          successEl.style.display = 'block';
          document.getElementById('amount').value = '';
          document.getElementById('category').value = '식비';
          document.getElementById('description').value = '';
          this.setTodayDate();
          this.loadExpenses();
        };

        request.onerror = () => {
          errorEl.textContent = '지출 추가 실패';
          errorEl.style.display = 'block';
        };
      }

      loadExpenses() {
        const transaction = this.db.transaction([this.expenseStore], 'readonly');
        const store = transaction.objectStore(this.expenseStore);
        const index = store.index('userEmail');
        const request = index.getAll(this.currentUser.email);

        request.onsuccess = () => {
          const expenses = request.result.sort((a, b) => new Date(b.date) - new Date(a.date));
          this.renderExpenses(expenses);
          this.updateSummary(expenses);
        };
      }

      renderExpenses(expenses) {
        const listEl = document.getElementById('expensesList');

        if (expenses.length === 0) {
          listEl.innerHTML = '<div class="empty-state">지출 기록이 없습니다</div>';
          return;
        }

        listEl.innerHTML = expenses.map(expense => `
          <div class="expense-item">
            <div class="expense-info">
              <span class="expense-category ${expense.category}">${this.getCategoryEmoji(expense.category)} ${expense.category}</span>
              <div class="expense-description">${expense.description || '설명 없음'}</div>
              <div class="expense-date">${expense.date}</div>
            </div>
            <div class="expense-amount">
              <strong>${expense.amount.toLocaleString()} 원</strong>
            </div>
            <div class="expense-actions">
              <button class="btn-edit" onclick="app.editExpense(${expense.id}, ${expense.amount}, '${expense.category}', '${expense.description || ''}', '${expense.date}')">수정</button>
              <button class="btn-delete" onclick="app.deleteExpense(${expense.id})">삭제</button>
            </div>
          </div>
        `).join('');
      }

      getCategoryEmoji(category) {
        const emojis = {
          '식비': '🍽️',
          '교통': '🚗',
          '쇼핑': '🛍️',
          '기타': '📌'
        };
        return emojis[category] || '📌';
      }

      updateSummary(expenses) {
        const currentMonth = new Date().getMonth();
        const currentYear = new Date().getFullYear();

        const thisMonthExpenses = expenses.filter(expense => {
          const expenseDate = new Date(expense.date);
          return expenseDate.getMonth() === currentMonth && expenseDate.getFullYear() === currentYear;
        });

        const total = thisMonthExpenses.reduce((sum, exp) => sum + exp.amount, 0);
        document.getElementById('totalExpense').textContent = total.toLocaleString() + ' 원';
      }

      deleteExpense(id) {
        if (!confirm('정말 삭제하시겠습니까?')) return;

        const transaction = this.db.transaction([this.expenseStore], 'readwrite');
        const store = transaction.objectStore(this.expenseStore);
        const request = store.delete(id);

        request.onsuccess = () => {
          this.loadExpenses();
        };

        request.onerror = () => {
          alert('삭제 실패');
        };
      }

      editExpense(id, amount, category, description, date) {
        document.getElementById('amount').value = amount;
        document.getElementById('category').value = category;
        document.getElementById('description').value = description;
        document.getElementById('date').value = date;
        document.getElementById('amount').focus();

        const oldAdd = this.addExpense.bind(this);
        this.addExpense = () => {
          const newAmount = parseFloat(document.getElementById('amount').value);
          const newCategory = document.getElementById('category').value;
          const newDescription = document.getElementById('description').value;
          const newDate = document.getElementById('date').value;
          const errorEl = document.getElementById('expenseError');
          const successEl = document.getElementById('expenseSuccess');

          errorEl.style.display = 'none';
          successEl.style.display = 'none';

          if (!newAmount || !newDate) {
            errorEl.textContent = '금액과 날짜를 입력해주세요';
            errorEl.style.display = 'block';
            return;
          }

          const transaction = this.db.transaction([this.expenseStore], 'readwrite');
          const store = transaction.objectStore(this.expenseStore);
          const expense = {
            id,
            userEmail: this.currentUser.email,
            amount: newAmount,
            category: newCategory,
            description: newDescription,
            date: newDate,
            createdAt: new Date().toISOString()
          };

          const request = store.put(expense);

          request.onsuccess = () => {
            successEl.textContent = '지출이 수정되었습니다';
            successEl.style.display = 'block';
            document.getElementById('amount').value = '';
            document.getElementById('category').value = '식비';
            document.getElementById('description').value = '';
            this.setTodayDate();
            this.loadExpenses();
            this.addExpense = oldAdd;
          };

          request.onerror = () => {
            errorEl.textContent = '지출 수정 실패';
            errorEl.style.display = 'block';
          };
        };
      }

      hashPassword(password) {
        return btoa(password);
      }

      verifyPassword(password, hash) {
        return btoa(password) === hash;
      }
    }

    const app = new ExpenseApp();
  </script>
</body>
</html>
EOF

